    "de": "euch",
    "lv": "Ты • Ты",
    "level": "A1",
    "study": {
      "id": "a1-euch",
      "layout": "standardStudy",
      "translation": "Ты • Ты",
      "explanation": "«Euch» — местоимение 2-го лица множественного числа. Употребляется как в качестве прямого дополнения (где?) – «ты», так и в качестве косвенного дополнения (кому?) – «тебе».",
      "examples": [
        {
          "de": "Ich sehe euch.",
          "lv": "Я тебя вижу"
        },
        {
          "de": "Ich helfe euch.",
          "lv": "Я помогу тебе"
        },
        {
          "de": "Ich gebe euch das Buch.",
          "lv": "Я даю тебе книгу"
        },
        {
          "de": "Ich danke euch.",
          "lv": "Я благодарю тебя"
        },
        {
          "de": "Ihr erinnert euch.",
          "lv": "Ты помнишь"
        }
      ],
      "comparison": [
        {
          "word": "ihr",
          "meaning": "Ты",
          "example": "Ihr seid freundlich. = Jūs esat draudzīgi."
        },
        {
          "word": "euch",
          "meaning": "Ты / тебе",
          "example": "Ich helfe euch. = Es jums palīdzu."
        },
        {
          "word": "euer",
          "meaning": "Твой",
          "example": "Das ist euer Haus. = Tā ir jūsu māja."
        }
      ],
      "info": [
        "Ihr = ты (подлежащее, форма предложения)",
        "Euch = ты (где? форма) / ты (кого? форма)",
        "Euer = ваш (притяжательная форма)"
      ],
      "tip": {
        "text": "\"euch\" отвечает на вопрос \"кому?\" или является прямым дополнением в предложениях со словом «ты».",
        "example": "Я помогу тебе. = Я помогу, ой. я вижу тебя = Ich sehe euch. Я говорю вам. = Ich erzähle euch."
      },
      "accents": {
        "blue": [
          "Их час"
        ],
        "yellow": [
          "Ой"
        ],
        "green": [
          "Эйер"
        ]
      }
    }
